package org.circus.core;
import java.io.*;import java.util.*;
/** Synthetic independent DC2 context producers and session save/restore contracts. */
public final class Dc2BorrowedTests {
 private static int checks;private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}private interface Work{void run()throws Exception;}private static void reject(Work w,String why)throws Exception{boolean bad=false;try{w.run();}catch(IOException expected){bad=true;}check(bad,why);}
 private static CircusResources data(byte... code)throws IOException{
  final byte[] mes=code,names=new byte[20];GameResources files=new GameResources(new GameResources.Storage(){public Set<String> paths(){return new HashSet<>(Arrays.asList("AdvData/MES/START.MES","AdvData/MES/OPTION.MES","AdvData/DAT/NAMES.DAT"));}private byte[] bytes(String p){return p.toLowerCase(Locale.ROOT).endsWith("names.dat")?names:mes;}public byte[] read(String p,int limit){return bytes(p).clone();}public Archive.Source source(String p){final byte[] b=bytes(p);return new Archive.Source(){public long size(){return b.length;}public byte[] read(long at,int n)throws IOException{Binary.range(at,n,b.length);return Arrays.copyOfRange(b,(int)at,(int)at+n);}};}});return new CircusResources(files,Profiles.get("dc2-3363"));
 }
 private static byte[] code(boolean auto){return auto?new byte[]{0,0,0,0,0x63,0x33,21,4,1,18,1,0,0,0,0}:new byte[]{0,0,0,0,0x63,0x33,28,50,0,18,1,0,21,4,0,0,0,0};}
 private static PcHost h(Dc2Session s){return(PcHost)s.host;}
 public static int run()throws Exception{
  checks=0;CircusResources data=data(code(false));Dc2Session s=new Dc2Session(data,TextCodec.identity());s.vm.variables.write(0,0,31);s.host.scene.slots[1]="producerA";s.host.audio[0]="musicA";s.dc2BorrowedCapture=()->new byte[]{1,2,3};
  check(s.vm.run(1)==MesVm.Status.RUNNING&&s.vm.offset()==9&&h(s).dc2Borrowed.producerKind()==1,"50 consumes its real three-byte head and captures after it");
  s.vm.variables.write(0,0,91);s.host.scene.slots[1]="liveB";s.host.audio[0]="musicB";h(s).write(99,254,2);s.vm.run(1);s.vm.elapse(200);check(s.vm.run(1)==MesVm.Status.WAIT_HOST&&s.host.saveRequest==2,"selected persist4 preserves independent50 caller");
  byte[] saved=s.dc2BorrowedSnapshot();Dc2Session loaded=new Dc2Session(data,TextCodec.identity());loaded.restore(saved);check(loaded.vm.offset()==9&&loaded.vm.variables.read(0,0)==31&&loaded.host.scene.slots[1].equals("producerA")&&loaded.host.audio[0].equals("musicA"),"slot continuation is producerA, not menuB");check(Arrays.equals(s.dc2BorrowedMetadata(),new byte[]{1,2,3}),"producer platform metadata stays paired");
  byte[] active=s.snapshot();Dc2Session copy=new Dc2Session(data,TextCodec.identity());copy.restore(active);check(Arrays.equals(active,copy.snapshot())&&copy.host.saveRequest==2,"active pending-save session retains independent leaf without recursion");
  byte[] bad=active.clone();bad[20]^=1;MesVm before=copy.vm;reject(()->copy.restore(bad),"corrupt session rejected");check(copy.vm==before,"failed restore cannot publish replacement host/VM");
  Dc2Session legacy=new Dc2Session(data,TextCodec.identity());legacy.restore(s.vm.snapshot());reject(legacy::requireDc2SaveCaller,"legacy CVS2 cannot fabricate missing borrowed leaf");
  byte[] meta=s.dc2BorrowedSnapshot(new Dc2BorrowedState.SaveMetadata(2026,11,7,23,59));Dc2Session dates=new Dc2Session(data,TextCodec.identity());dates.restore(meta);check(dates.vm.variables.read(0,0)==31&&dates.vm.variables.read(9,21)==11&&dates.vm.variables.read(9,25)==26,"date patch preserves producer ordinary except original metadata bytes");
  Dc2Session auto=new Dc2Session(data(code(true)),TextCodec.identity());auto.vm.variables.write(0,0,77);check(auto.vm.run(1)==MesVm.Status.WAIT_HOST&&auto.host.saveRequest==0,"native automatic persist4 writes slot0");Dc2Session resumed=new Dc2Session(data(code(true)),TextCodec.identity());resumed.restore(auto.dc2BorrowedSnapshot());check(resumed.host.saveRequest<0&&resumed.vm.offset()==9&&resumed.vm.run(1)==MesVm.Status.WAIT_HOST,"current-auto leaf clears pending request and reaches following wait");
  CircusResources waitingData=data((byte)0,(byte)0,(byte)0,(byte)0,(byte)0x63,(byte)0x33,(byte)28,(byte)50,(byte)0,(byte)10,(byte)0,(byte)0,(byte)0,(byte)0,(byte)0);Dc2Session quick=new Dc2Session(waitingData,TextCodec.identity());quick.vm.run(1);quick.vm.run(1);quick.vm.variables.write(0,0,63);quick.host.audio[5]="voice-present";quick.requestDc2QuickSave();check(quick.host.saveRequest==0&&h(quick).dc2Borrowed.producerKind()==4,"native q unconditionally refreshes and selects0");Dc2Session qcopy=new Dc2Session(waitingData,TextCodec.identity());qcopy.restore(quick.dc2BorrowedSnapshot());check(qcopy.vm.variables.read(0,0)==63&&qcopy.host.audio[5].equals("voice-present"),"quick action retains current voice in its independent caller");
  Dc2Session event=new Dc2Session(waitingData,TextCodec.identity());event.vm.run(1);event.vm.run(1);event.host.audio[5]="voice";event.openSystem("OPTION");check(event.inSystem()&&h(event).dc2Borrowed.producerKind()==3,"flag0 native menu event refreshes borrowed caller");byte[] menu=event.snapshot();Dc2Session ecopy=new Dc2Session(waitingData,TextCodec.identity());ecopy.restore(menu);check(ecopy.inSystem(),"F5 in external system menu preserves separate suspended caller");ecopy.returnToStory();check(!ecopy.inSystem()&&ecopy.vm.scriptName().equals("START")&&ecopy.host.audio[5].isEmpty(),"native menu return restores caller with event's stopped voice");
  Dc2Session failure=new Dc2Session(data,TextCodec.identity());failure.dc2BorrowedCapture=()->{throw new IOException("metadata failure");};check(failure.vm.run(1)==MesVm.Status.FAULT&&failure.vm.offset()==9,"failed metadata capture stops before another instruction");
  Dc2Session retry=new Dc2Session(waitingData,TextCodec.identity());retry.vm.run(2);retry.dc2BorrowedCapture=()->{throw new IOException("preview failure");};reject(retry::requestDc2QuickSave,"failed synchronous quick capture remains an error");check(retry.host.saveRequest<0&&!retry.inSystem(),"failed quick capture does not invent a pending write/menu");reject(retry::snapshot,"failed replacement cannot write an unloadable mismatched session");retry.dc2BorrowedCapture=()->new byte[]{4};retry.requestDc2QuickSave();check(retry.host.saveRequest==0&&retry.dc2BorrowedMetadata()[0]==4,"a real retried quick producer may replace failed capture");
  h(s).dc2LocalHour=()->23;check(h(s).read(99,21)==23,"99:21 is local hour, not slot existence");h(s).dc2LocalHour=()->0;check(h(s).read(99,21)==0,"midnight native hour is0");h(s).dc2LocalHour=()->24;reject(()->h(s).read(99,21),"invalid platform clock rejected");
  return checks;
 }
 public static void main(String[]args)throws Exception{System.out.println("Dc2BorrowedTests "+run()+" PASS");}
}
